mapper.update:
UPDATE pipeline_dedup_group
SET file_paths = #{filePaths}, file_names = #{fileNames}
WHERE id = #{id}

mapper.delete:
DELETE FROM pipeline_dedup_group
WHERE pipeline_id = #{pipelineId}
  AND (file_paths = '[]' OR file_paths = '' OR file_paths IS NULL)

DELETE FROM pipeline_dedup_group
WHERE pipeline_id IN (
    SELECT id FROM pipeline_task
    WHERE state IN ('COMPLETED', 'FAILED', 'CANCELLED')
      AND create_time < #{before}
)
